head.script:
        scwin.onpageload = function() {

        };

	scwin.checkVal1 = function(elem) {
		var aTag = WebSquare.wUnit.getDomById(elem);

		var hasEm = false;
		var hasI = false;	
		for (var i = 0; i < aTag.children.length; i++) {
			var child = aTag.children[i];
			var tag = child.tagName.toLowerCase();

			if (tag === "em") {
				hasEm = true;
			} else if (tag === "i") {
				hasI = true;
			}
		}

		return hasEm && hasI;
	}	

	scwin.unitTest = function() {
		//noResult="previous"
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1('wq_uuid_4')", "true");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1('wq_uuid_8')", "true");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1('wq_uuid_12')", "true");
		WebSquare.wUnit.addCommand("pause", "400");

		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
